 "노드 설정": "Cài đặt nút",
 "노드를 누르면 여기서 고쳐요. 출력 점을 끌어 다음 노드에 이어요. 앞 노드로 이으면 되돌아가는 선이 돼요. 선을 누르면 선 설정이 열려요. 휠로 확대·축소하고, 휠 클릭이나 스페이스를 누른 채 끌면 화면이 움직여요.": "Bấm vào một nút để sửa ở đây. Kéo chấm đầu ra để nối với nút tiếp theo; nối về nút phía trước sẽ tạo thành đường quay lại. Bấm vào đường để mở cài đặt của đường. Cuộn chuột để phóng to/thu nhỏ; nhấn giữa chuột rồi kéo, hoặc giữ phím Space rồi kéo để di chuyển màn hình.",
 "노드": "Nút",
 "되돌아가는 선": "Đường quay lại",
 "고르세요": "Hãy chọn",
 "출력이 {\"ok\": true/false, …}면 통과·실패 갈래로 나뉘어요. 처음 한 번은 빌드에 1~2초, 30초 안에 끝나야 해요. 토큰은 들지 않아요.": "Nếu đầu ra là {\"ok\": true/false, …} thì sẽ chia thành nhánh đạt và nhánh lỗi. Lần đầu tiên mất 1–2 giây để dựng và phải xong trong vòng 30 giây. Không tốn token.",
 "배포·게시처럼 되돌릴 수 없는 단계 바로 앞에 두세요. 답이 올 때까지 멈춰요.": "Hãy đặt ngay trước những bước không thể hoàn tác như triển khai hoặc đăng bài. Nó sẽ dừng lại cho đến khi có câu trả lời.",
