 "앱·메일·웹·문서에 쓰는 색·글꼴·규칙 모음이에요. 하나를 고르면 오른쪽에서 자세히 볼 수 있어요.": "Bộ sưu tập màu sắc, phông chữ và quy tắc dùng cho ứng dụng, email, web và tài liệu. Chọn một bộ để xem chi tiết ở bên phải.",
 "슬라이드 프롬프트": "Prompt slide",
