 "발표·보고용 슬라이드 프롬프트와 만드는 스크립트를 모아 둬요. 카드를 고르면 오른쪽에서 고치고 바로 만들 수 있어요.": "Lưu các prompt slide cho thuyết trình, báo cáo cùng script để tạo chúng. Chọn một thẻ để chỉnh sửa ở bên phải và tạo ngay.",
 "자주 쓰는 이미지 프롬프트를 예시 이미지와 함께 모아 둬요. 모델과 카테고리로 골라 보세요.": "Lưu các prompt ảnh hay dùng cùng ảnh minh họa. Hãy lọc theo mô hình và danh mục.",
