 "같은 작업에서 이어서 쓰인 스킬 순서예요. 관찰한 것일 뿐, 실행 허가는 아니에요.": "Đây là thứ tự các skill được dùng nối tiếp nhau trong cùng một tác vụ. Chỉ là quan sát, không phải cho phép chạy.",
 "대화에서 관찰한 사용자 성향이에요. 지시나 실행 승인으로 쓰지 않아요.": "Đây là xu hướng của người dùng được quan sát trong cuộc trò chuyện. Không dùng làm chỉ thị hay chấp thuận để thực hiện.",
 "작업하면서 얻은 해석이에요. 사실이나 실행 승인으로 쓰지 않아요.": "Đây là những nhận định rút ra khi làm việc. Không dùng làm sự thật hay chấp thuận để thực hiện.",
 "정한 시각에 쓰이던 기억을 그대로 보여 줘요. 지금 지시로는 쓰지 않아요.": "Hiển thị nguyên vẹn các ký ức đã được dùng vào thời điểm bạn chọn. Không dùng làm chỉ thị hiện tại.",
 "에이전트와 나눈 대화예요. 7일 보관하고, 기억이 실제로 쓰이면 그때부터 다시 7일을 세요.": "Đây là các cuộc trò chuyện với agent. Được giữ 7 ngày, và khi một ký ức thực sự được dùng thì 7 ngày được tính lại từ đó.",
