 "제품별·목적별로 디자인 시스템을 모아 둬요. 오른쪽 위 ‘디자인 시스템 추가’로 넣고, 이 앱의 실제 색·글자·부품은 ‘Arkism 토큰’에서 봐요.": "Gom các hệ thống thiết kế theo sản phẩm và mục đích. Thêm bằng ‘Thêm hệ thống thiết kế’ ở góc trên bên phải; màu, chữ và thành phần thật của ứng dụng này nằm trong ‘Token Arkism’.",
