 "바탕이 바뀌었거나 주제 수가 꽉 차서 처리하지 못했어요. 새로 불러왔어요. (꽉 찼다면 합치기 후보를 먼저 승인하세요)": "Không xử lý được vì nguồn đã thay đổi hoặc số chủ đề đã đầy. Đã tải lại. (Nếu đã đầy, hãy duyệt bản nháp gộp trước)",
