 "답에 보였는지": "Có xuất hiện trong câu trả lời không",
 "아직 서버가 답에 보였는지 기록을 보내지 않았어요.": "Máy chủ chưa gửi bản ghi về việc ký ức có xuất hiện trong câu trả lời hay không.",
 "질문할 때 찾아 넣은 기억의 문구가 답에 보였는지만 세요. 실제 활용 여부는 측정하지 않았고, 읽지 못한 대화 수는 이 통계에서 알 수 없어요.": "Chỉ đếm xem nội dung của ký ức được tìm ra khi đặt câu hỏi có xuất hiện trong câu trả lời hay không. Chưa đo việc có thật sự được dùng hay không, và thống kê này không cho biết số cuộc trò chuyện chưa đọc được.",
 "답에 보인 기억이 아직 없어요.": "Chưa có ký ức nào xuất hiện trong câu trả lời.",
