 "답에 안 보임": "Không xuất hiện trong câu trả lời",
 "최근 호출 없음": "Gần đây không được gọi",
 "기억이 답에 보였는지는 PC 수집기가 보고하면 여기에 보여요. 실제 활용 여부는 측정하지 않아요.": "Khi bộ thu thập trên PC báo cáo, việc ký ức có xuất hiện trong câu trả lời hay không sẽ hiển thị ở đây. Chưa đo việc có thật sự được dùng hay không.",
 "답에 안 보임 · 직접 검토": "Không xuất hiện trong câu trả lời · Tự xem lại",
 "답에 보인 비율": "Tỷ lệ xuất hiện trong câu trả lời",
 "답에 보임": "Xuất hiện trong câu trả lời",
