 "전달한 기억 중 답에 보인 비율": "Tỷ lệ ký ức đã gửi có xuất hiện trong câu trả lời",
 "재검토 예정일이 지났거나 최근에 잘 안 불리거나 답에 잘 안 보여요. 직접 확인해 주세요": "Đã quá ngày xem lại, hoặc gần đây ít được gọi hay ít xuất hiện trong câu trả lời. Vui lòng tự kiểm tra",
 "승인 기록": "Lịch sử phê duyệt",
 "재검토 예정일이 지났거나 최근에 잘 안 불리거나 답에 잘 안 보이는 기억이에요. 실제 활용 여부와는 구분해요.": "Đây là các ký ức đã quá ngày xem lại, hoặc gần đây ít được gọi hay ít xuất hiện trong câu trả lời. Điều này khác với việc có thật sự được dùng hay không.",
 "재검토 예정일 지남": "Quá ngày xem lại",
 "확인하기": "Kiểm tra",
 "펼치면 서로 다른 원문 발화 수를 확인해요. 횟수는 승인이나 신뢰 점수가 아니에요.": "Mở ra để xem số lượt phát ngôn gốc khác nhau. Số lần không phải là điểm phê duyệt hay độ tin cậy.",
 "각 문장의 조건과 예외를 확인하고 항목별로 결정해 주세요.": "Hãy xem điều kiện và ngoại lệ của từng câu rồi quyết định riêng cho từng mục.",
 "원문 근거를 확인하는 중…": "Đang kiểm tra căn cứ trong nguyên văn…",
 "재검토 예정일이 지났어요": "Đã quá ngày xem lại",
 "대화에서 기억할 만한 내용을 찾아요. 저장할지는 사람이 정해요.": "Tìm những nội dung đáng nhớ trong cuộc trò chuyện. Có lưu hay không là do bạn quyết định.",
 "재검토 예정일이 지났어요. 내용이 아직 맞는지 직접 확인해 주세요.": "Đã quá ngày xem lại. Vui lòng tự kiểm tra xem nội dung còn đúng không.",
 "최근 30일 동안 검색으로 전달된 기록이 없어요. 실제 활용 여부와 내용의 필요성은 따로 확인해 주세요.": "Trong 30 ngày qua không có bản ghi nào được gửi qua tìm kiếm. Hãy tự kiểm tra riêng việc có thật sự được dùng và nội dung còn cần thiết không.",
 "기억 관리": "Quản lý ký ức",
 "정정 또는 충돌 검토가 대기 중이에요. 기존 기억이 계속 전달될 수 있으니 먼저 확인해 주세요.": "Đang có yêu cầu xem xét chỉnh sửa hoặc xung đột. Ký ức cũ vẫn có thể được gửi đi, nên hãy kiểm tra trước.",
