 "연결되면 이 PC의 키체인(자격 증명 관리자)에 저장해 다시 묻지 않아요. 비워 두면 저장된 비밀번호를 써요": "Khi kết nối được, mật khẩu sẽ lưu trong chuỗi khóa (Credential Manager) của máy này nên sẽ không hỏi lại. Để trống để dùng mật khẩu đã lưu",
 "서버의 Git·스킬 화면은 이 연결로 돼요. 에이전트의 기억 수집은 SSH 키가 있어야 서버로 가요.": "Màn hình Git và Kỹ năng của máy chủ dùng kết nối này. Việc thu thập ký ức của tác nhân chỉ đến được máy chủ khi có khóa SSH.",
 "SSH 키 또는 ssh-agent로 로그인해요": "Đăng nhập bằng khóa SSH hoặc ssh-agent",
