 "SSH 키 또는 비밀번호로 접속해요. 비밀번호는 이 PC의 키체인에 저장해 다시 묻지 않고, 연결 끊기를 누르면 지금 연결된 서버의 비밀번호를 지워요.": "Đăng nhập bằng khóa SSH hoặc mật khẩu. Mật khẩu được lưu trong chuỗi khóa của máy này nên sẽ không hỏi lại; khi bạn nhấn Ngắt kết nối, mật khẩu của máy chủ đang kết nối sẽ bị xóa.",
