 "개발 빌드": "Bản phát triển",
 "토큰은 Arkism에 암호화해 저장하고, 화면에는 끝 4자리만 보여요. 디스코드 개발자 포털에서 봇을 만들고 Message Content Intent를 켠 뒤 토큰을 넣어 주세요.": "Token được mã hóa và lưu trong Arkism, màn hình chỉ hiện 4 ký tự cuối. Hãy tạo bot trong cổng nhà phát triển Discord, bật Message Content Intent rồi dán token vào.",
 "토큰은 Arkism에 저장하고, 화면에는 끝 4자리만 보여요. @BotFather로 만든 봇을 그룹이나 DM에 먼저 추가해 두세요.": "Token được lưu trong Arkism, màn hình chỉ hiện 4 ký tự cuối. Hãy thêm bot đã tạo bằng @BotFather vào nhóm hoặc DM trước.",
 "웹훅 주소는 Arkism에 저장하고, 화면에는 끝 4자리만 보여요. 슬랙의 Incoming Webhooks에서 만들어요.": "Địa chỉ webhook được lưu trong Arkism, màn hình chỉ hiện 4 ký tự cuối. Bạn tạo nó ở Incoming Webhooks của Slack.",
 "바꾸려면 팀·전문가 상세의 채널 연결에서 해요.": "Muốn đổi thì vào phần Kết nối kênh trong chi tiết của nhóm hoặc chuyên gia.",
 "아직 답이 없어요. 잠시 뒤 다시 확인해 주세요.": "Chưa có phản hồi. Hãy kiểm tra lại sau ít phút.",
 "10분 안에 로그인이 끝나지 않았어요. 다시 눌러 주세요.": "Đăng nhập chưa xong trong 10 phút. Hãy bấm lại.",
 "로그인 창을 열지 못했어요. 터미널에서 아래 명령을 실행해 주세요.": "Không mở được cửa sổ đăng nhập. Hãy chạy lệnh bên dưới trong terminal.",
 "로그인은 됐지만 계정을 넣지 못했어요. 다시 눌러 주세요.": "Đã đăng nhập nhưng chưa thêm được tài khoản. Hãy bấm lại.",
 "로그인 버튼을 누르면 로그인 창이 열려요. 브라우저에서 로그인을 마치면 여기 바로 보여요.": "Bấm nút đăng nhập để mở cửa sổ đăng nhập. Khi bạn đăng nhập xong trong trình duyệt, kết quả sẽ hiện ngay ở đây.",
 "로그인 창을 열었어요": "Đã mở cửa sổ đăng nhập",
 "브라우저에서 로그인을 마치면 여기서 바로 알려 줘요. 창을 닫지 마세요.": "Khi bạn đăng nhập xong trong trình duyệt, ở đây sẽ báo ngay. Đừng đóng cửa sổ này.",
 "이제 이 계정으로 AI를 쓸 수 있어요.": "Bây giờ bạn có thể dùng AI bằng tài khoản này.",
 "로그인하지 못했어요. 다시 눌러 주세요.": "Không đăng nhập được. Hãy bấm lại.",
 "로그인돼 있어요": "Đã đăng nhập",
 "아직 로그인 안 됨": "Chưa đăng nhập",
 "다른 계정으로 로그인": "Đăng nhập bằng tài khoản khác",
 "구독 대신 API 키로 연결해요": "Kết nối bằng khóa API thay vì gói đăng ký",
 "로그인한 계정이 없어요. 구독으로 쓰려면 계정을 추가하고, API로 쓰려면 아래 'API 키'에서 키를 넣어요.": "Chưa có tài khoản nào đăng nhập. Muốn dùng gói đăng ký thì thêm tài khoản, muốn dùng API thì nhập khóa ở mục 'Khóa API' bên dưới.",
 "로그인하거나 API 키를 넣으면 이 모델들을 쓸 수 있어요.": "Đăng nhập hoặc nhập khóa API thì bạn có thể dùng các mô hình này.",
 "아직 받은 모델이 없어요. '목록 새로고침'으로 다시 받아 보세요.": "Chưa nhận được mô hình nào. Hãy thử 'Làm mới danh sách'.",
 "이 PC의 Arkism이 아직 로그인 상태를 읽는 중이에요. 잠시 뒤 보여요.": "Arkism trên máy này vẫn đang đọc trạng thái đăng nhập. Sẽ hiện sau ít phút.",
 "잠시 뒤 다시 시험해 주세요.": "Hãy thử lại sau ít phút.",
 "아직 저장되지 않았어요. 잠시 뒤 다시 열어 확인해 주세요.": "Chưa được lưu. Hãy mở lại sau ít phút để kiểm tra.",
