 "AI 연결하기": "Kết nối AI",
 "AI를 하나 연결하면 Arkism이 기억과 스킬을 그 AI에 이어 줘요.": "Kết nối một AI thì Arkism sẽ nối ký ức và kỹ năng của bạn với AI đó.",
 "쓸 AI 고르기": "Chọn AI để dùng",
 "로그인하거나 API 키 넣기": "Đăng nhập hoặc nhập khóa API",
